import {fieldPage,bindField} from './field-lab.js';
import {simpleMarkup} from './simple-lessons.js';
import {practitionerPage,bindPractitioner} from './practitioner-ui.js';
import {workbenchPage,bindWorkbench} from './workbench.js';
import {v2CoverageMarkup} from './coverage-v2.js';
let coverageVersion='v2.0';
import {allocateVlsm,vlsmPage,vlsmResult,vlsmText} from './vlsm.js';
import {selectPractice} from './assessment.js';
import {evidencePanel,evidenceText,validateEvidence} from './evidence.js';
import {topologyMarkup,topologyText} from './topologies.js';
import {modules,lessons,cards,sources} from './course.js';
import {labs,packetEvents} from './labs.js';
import {questions} from './questions.js';
import {domains,objectives,glossary} from './coverage.js';
let evidenceDrafts={};try{evidenceDrafts=JSON.parse(localStorage.getItem('netpath-evidence-drafts')||'{}');if(!evidenceDrafts||typeof evidenceDrafts!=='object'||Array.isArray(evidenceDrafts))evidenceDrafts={};}catch{}
let glossarySearch='';
import {subnet,nextReview,shuffled,createTerminal,terminalCommand} from './logic.js';
const app=document.querySelector('#app');let state,token,queue=Promise.resolve(),quiz=null,busy=false,tab='subnet',reviewId=null,flipped=false,step=0,trainer={ip:'192.168.8.77',prefix:26,answer:'',result:null,feedback:''},terminal=createTerminal(),lines=['NetPath command sandbox. Type help for supported commands.'],filter='all',search='',noteTimer;
const $=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)],esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const navs=[['overview','Overview','◫'],['field','Field lab','⌁'],['path','Learning path','▤'],['labs','Packet Tracer labs','◇'],['practice','Practice studio','⌘'],['practitioner','Practitioner exams','◇'],['workbench','Network workbench','⌕'],['review','Review cards','↻'],['notes','My notes','▧'],['progress','Progress','▥'],['plan','Study plan','◷'],['coverage','Exam objectives','◎'],['glossary','Glossary','Aa'],['settings','Settings & backups','⚙']];
const done=id=>state.completed.includes(id),pct=(a,b)=>b?Math.round(a/b*100):0,due=()=>cards.filter(c=>done(c.id)&&(!state.cards[c.id]||state.cards[c.id].due<=Date.now())),labDone=l=>(state.labs[l.id]||[]).length===l.steps.length;
function toast(s){const t=$('#toast');t.textContent=s;t.style.display='block';clearTimeout(t.hide);t.hide=setTimeout(()=>t.style.display='none',6500);}
async function api(url,body){const r=await fetch(url,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-NetPath-Token':token},body:JSON.stringify(body)}),j=await r.json();if(!r.ok)throw Error(j.error||'Request failed.');return j;}
function save(fn){const job=queue.then(async()=>{const next=structuredClone(state);fn(next);state=(await api('/api/state',next)).state;return true;});queue=job.catch(()=>{});return job.catch(e=>{toast('Not saved: '+e.message);return false;});}
function route(){const [page,id]=location.hash.slice(1).split('/');return {page:page||'overview',id};}
function go(dest){if(location.hash==='#'+dest)render();else location.hash=dest;}
function header(k,t,d,a=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p class="muted">${d}</p></div>${a}</div>`;}
function flow(names=['PC-A','Switch','PC-B']){return `<div class="learning-flow">${names.map((n,i)=>`${i?'<span class="wire" aria-hidden="true">──</span>':''}<div class="device"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="${i===1?'M2 7h20v10H2z M5 10h2 M10 10h2 M15 10h2 M5 14h2 M10 14h2 M15 14h2':'M3 4h18v13H3z M8 21h8 M12 17v4'}"/></svg><strong>${esc(n)}</strong></div>`).join('')}</div>`;}
function moduleCard(m){const ls=lessons.filter(l=>l.module===m.id);return `<div class="card module"><div class="number">${String(modules.indexOf(m)+1).padStart(2,'0')}</div><div class="grow"><h3>${m.name}</h3><p class="muted">${ls.length} lessons · ${ls.filter(l=>done(l.id)).length} completed</p></div><button class="ghost" data-module="${m.id}" aria-label="Explore ${m.name}">→</button></div>`;}
function overview(){const next=lessons.find(l=>!done(l.id))||lessons[0];return header('YOUR PERSONAL CLASSROOM',`Good to see you, ${esc(state.settings.name)}.`,`A little understanding today. A stronger network tomorrow.`)+`<div class="grid"><section class="card feature"><span class="badge green">${state.completed.length?'CONTINUE YOUR JOURNEY':'START WITH THE FUNDAMENTALS'}</span><h2>${next.title}</h2><p class="muted">${next.goal}</p><div class="row small muted" style="margin:24px 0"><span>Lesson ${String(next.number).padStart(2,'0')}</span><span>·</span><span>${next.minutes} min</span></div><button class="primary" data-go="lesson/${next.id}">${state.completed.length?'Continue learning':'Start first lesson'} →</button></section><section class="card"><div class="row between"><span class="eyebrow">LEARN BY DOING</span><span class="badge">25 min</span></div>${flow()}<h3>Two computers. One conversation.</h3><p class="muted small">Build your first LAN and watch a packet travel.</p><button class="ghost" data-go="lab/first-lan">Open visual lab guide →</button></section></div><div class="stats"><div class="card stat"><strong>${state.completed.length}<span class="muted" style="font-size:16px"> / ${lessons.length}</span></strong><small>Lessons completed</small></div><div class="card stat"><strong>${due().length}</strong><small>Cards ready to review</small></div><div class="card stat"><strong>${labs.filter(labDone).length}<span class="muted" style="font-size:16px"> / ${labs.length}</span></strong><small>Lab checklists completed</small></div></div><div class="grid"><section><div class="row between" style="margin-bottom:18px"><h2 style="margin:0">Your learning path</h2><button class="ghost" data-go="path">View all</button></div><div class="modules">${modules.slice(0,4).map(moduleCard).join('')}</div></section><aside><section class="card"><span class="eyebrow">TODAY’S STUDY SESSION</span><h3 style="margin-top:16px">Make it a focused 30 minutes.</h3><p class="small muted">10 min to revisit an idea · 15 min to practice · 5 min to explain what you learned.</p><button class="primary" data-go="review">Review your learning →</button></section><section class="card section"><span class="eyebrow">EXAM PLANNING</span><h3 style="margin-top:16px">Learn now. Choose your target.</h3><p class="small muted">This starter curriculum maps to v1.1. Cisco’s v2.0 launches February 3, 2027. The objective tracker now includes a preliminary v2.0 map with explicit development gaps.</p><button class="ghost" data-go="settings">Set study preferences →</button></section></aside></div>`;}
function pathPage(){return header('A STRUCTURED WAY FORWARD','Your learning path','Build a foundation, then connect the pieces.')+`<div class="toolbar"><input id="search" class="search" aria-label="Search lessons" placeholder="Search lessons or topics…" value="${esc(search)}"><select id="filter" aria-label="Filter module" style="max-width:300px"><option value="all">All modules</option>${modules.map(m=>`<option value="${m.id}" ${filter===m.id?'selected':''}>${m.name}</option>`).join('')}</select></div>${modules.filter(m=>filter==='all'||m.id===filter).map(m=>{const ls=lessons.filter(l=>l.module===m.id&&(l.title+' '+l.sections.map(s=>s.text).join(' ')).toLowerCase().includes(search.toLowerCase()));return ls.length?`<section class="section"><div class="row between"><h2>${m.name}</h2><span class="badge">${m.domain}</span></div><p class="muted small">${m.description}</p><div class="modules">${ls.map(l=>`<article class="card module"><div class="number">${done(l.id)?'✓':String(l.number).padStart(2,'0')}</div><div class="grow"><h3>${l.title}</h3><p class="muted">${l.minutes} min · ${l.goal}</p></div><button data-go="lesson/${l.id}">${done(l.id)?'Revisit':'Learn'} →</button></article>`).join('')}</div></section>`:'';}).join('')||'<p>No matching lessons.</p>'}`;}
function noteBox(id,label){return `<label for="note">${label}</label><textarea id="note" data-note="${id}" placeholder="Write your explanation, observations, or command output…">${esc(state.notes[id]||'')}</textarea><p class="small muted" id="note-status">Saved locally as you type.</p>`;}
function lessonPage(id){const l=lessons.find(x=>x.id===id);if(!l)return missing();const prev=lessons[l.number-2],next=lessons[l.number],lessonLabs=labs.filter(x=>x.lesson===id);return header(`LESSON ${String(l.number).padStart(2,'0')} · ${l.minutes} MIN`,l.title,l.goal,'<button data-go="path">← Learning path</button>')+`<div class="lesson-layout"><article class="card prose">${prev&&!done(prev.id)?`<p class="small muted">Suggested first: <a href="#lesson/${prev.id}">${prev.title}</a>. You can still explore this lesson now.</p>`:''}<label class="check"><input id="simple-mode" type="checkbox" ${state.settings.simpleLessons?'checked':''}><span>Simplified lesson mode</span></label>${state.settings.simpleLessons?simpleMarkup(id):l.sections.map(s=>`<h3>${s.heading}</h3><p>${esc(s.text)}</p>`).join('')}<div class="callout"><strong>Remember this</strong><p style="margin:6px 0 0">${esc(l.takeaway)}</p></div>${['journey','ethernet','layers'].includes(id)?flow()+'<button data-tablink="packet">Explore the packet walkthrough →</button>':''}${id==='vlsm'?'<button data-tablink="vlsm">Open saved VLSM planner →</button>':''}<h3>Try it yourself</h3><p>${esc(l.exercise)}</p>${lessonLabs.map(lab=>`<button class="primary" data-go="lab/${lab.id}">${esc(lab.title)} →</button>`).join(' ')}${l.workshop?`<section class="workshop section"><span class="eyebrow">INDEPENDENT EXERCISE</span><h3>Predict before you reveal.</h3><p>${esc(l.workshop.task)}</p><details><summary>Reveal the reasoning</summary><p>${esc(l.workshop.answer)}</p></details>${l.workshop.commands?`<details><summary>Useful commands for the lab</summary><pre>${esc(l.workshop.commands)}</pre><p class="small muted">Use on simulated devices. Check your model’s supported commands.</p></details>`:''}</section>`:''}<h3>Check your understanding</h3><p>${esc(l.question.prompt)}</p><div class="options">${l.question.options.map((o,i)=>`<button class="option" data-answer="${i}" data-lesson="${id}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><div id="lesson-feedback" aria-live="polite"></div><div class="row between section"><button class="primary" id="complete" data-id="${id}">${done(id)?'Completed ✓':'Mark lesson complete'}</button>${next?`<button data-go="lesson/${next.id}">Next lesson →</button>`:'<button data-go="progress">View progress →</button>'}</div><p class="footer-note">Completion records that you studied the lesson. Assessment results and lab evidence are tracked separately.</p></article><aside class="lesson-aside"><section class="card"><span class="eyebrow">LESSON NOTES</span><div class="section">${noteBox(id,'Explain it in your own words.')}</div></section><section class="card section"><span class="eyebrow">CURRICULUM REFERENCE</span><p class="section">${esc(l.objectives)}</p><p class="small muted">${l.objectives==='NetPath specialist extension'?'Independent NetPath specialist workshop; not an additional official exam domain.':l.objectives.startsWith('v2.0')?'Supplemental v2.0 instruction. Practical platform validation remains separate.':l.module==='beyond'?'Applied extension, not an additional exam domain.':'Mapped to CCNA v1.1. This concise lesson is a starting point, not exhaustive exam coverage.'}</p><a class="small" href="${sources[0].url}" target="_blank" rel="noreferrer">Official blueprint ↗</a></section></aside></div>`;}
function labsPage(){return header('PUT THE THEORY TO WORK','Packet Tracer lab companion','Visual topologies, configuration steps, and evidence-based checkpoints.')+`<div class="callout small"><strong>Companion mode</strong> · Open Packet Tracer beside this guide. Checklists are self-reported; NetPath is not connected to your live simulator. These guides still need validation in your installed build.</div><div class="lab-list section">${labs.map(l=>`<article class="card"><div class="row between"><span class="badge ${labDone(l)?'green':''}">${labDone(l)?'Checklist complete':l.level}</span><span class="small muted">${l.minutes} min</span></div>${flow(l.devices)}<h3>${l.title}</h3><p class="muted small">${l.subtitle}</p><div class="progress"><div style="width:${pct((state.labs[l.id]||[]).length,l.steps.length)}%"></div></div><div class="row between"><span class="small muted">${(state.labs[l.id]||[]).length}/${l.steps.length} steps checked</span><button data-go="lab/${l.id}">Open guide →</button></div></article>`).join('')}</div>`;}
function simulation(){const e=packetEvents[step];return `<span class="eyebrow">ILLUSTRATED PACKET WALKTHROUGH</span>${flow()}<div class="packet-track" aria-label="Step ${step+1} of 6">${packetEvents.map((_,i)=>`<span class="${i<=step?'on':''}"></span>`).join('')}</div><span class="badge green">${e.label}</span><div class="event"><h3 style="margin-top:16px">${e.title}</h3><p class="muted">${e.text}</p></div><div class="row between"><button data-sim="-1" ${!step?'disabled':''}>← Previous</button><span class="small muted">${step+1} / 6</span><button class="primary" data-sim="1" ${step===5?'disabled':''}>Next event →</button></div><p class="footer-note">Conceptual sequence. Use Packet Tracer’s Simulation → Edit Filters → ARP / ICMP → Capture/Forward to inspect actual events.</p>`;}
function labPage(id){const l=labs.find(x=>x.id===id);if(!l)return missing();return header(`${l.level.toUpperCase()} · ${l.minutes} MIN`,l.title,l.subtitle,'<button data-go="labs">← All labs</button>')+`<div class="lesson-layout"><article><section class="card"><div class="row between"><span class="eyebrow">BUILD THIS TOPOLOGY</span><span class="badge">Diagram · not live</span></div><div id="lab-topology">${topologyMarkup(id)}</div>${id==='first-lan'?'<div class="callout small"><strong>Native starter available</strong><p>A topology-only .pkt file created in Packet Tracer 9.0.1. PC0 corresponds to PC-A; PC1 corresponds to PC-B. Configure addresses using this guide. End-to-end behavior has not yet been validated.</p><a href="/native-labs/first-lan-starter.pkt" download>Download first LAN starter (.pkt)</a></div>':''}<div class="table-wrap"><table><thead><tr>${['Device','Interface','Address','Mask','Gateway'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${l.addresses.map(a=>`<tr>${a.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>${l.simulation?`<section class="card section" id="simulation">${simulation()}</section>`:''}<section class="card section"><h2>Your lab walkthrough</h2><p class="muted small">Check a step after you observe its expected result. Checkmarks save automatically.</p>${l.steps.map((s,i)=>`<section class="step"><label class="check"><input type="checkbox" data-lab="${id}" data-step="${i}" ${(state.labs[id]||[]).includes(i)?'checked':''}><span><strong>${i+1}. ${s.title}</strong></span></label><p style="margin:12px 0">${esc(s.action)}</p><div class="callout small"><strong>Expected result</strong><br>${esc(s.expected)}</div><details><summary>Need a hint?</summary><p class="small muted">${esc(s.hint)}</p></details></section>`).join('')}<div class="callout"><strong>Independent challenge</strong><p style="margin:8px 0 0">${esc(l.challenge)}</p></div></section>${evidencePanel(id,state.evidence?.[id]||[],evidenceDrafts[id]||{})}</article><aside class="lesson-aside"><section class="card"><div class="row between"><span class="eyebrow">COMMAND REFERENCE</span><button id="copy" data-id="${id}">Copy</button></div><pre>${esc(l.commands)}</pre><p class="small muted">Lines starting with ! are comments. Match interface names to your device. These are guide examples, not verified native .pkt/.pka files.</p><button id="download-lab" data-id="${id}">Download guide (.txt)</button></section><section class="card section">${noteBox('lab:'+id,'Evidence & observations')}</section><section class="card section"><h3>Related concept</h3><button data-go="lesson/${l.lesson}">Open lesson →</button></section></aside></div>`;}
function practicePage(){return header('PRACTICE WITH PURPOSE','Your practice studio','Build fluency in small, focused sessions.')+`<div class="tabs">${[['subnet','Subnetting'],['vlsm','VLSM planner'],['terminal','Command practice'],['packet','Packet walkthrough'],['assessment','Knowledge check']].map(([id,n])=>`<button class="${tab===id?'active':''}" data-tab="${id}">${n}</button>`).join('')}</div>${tab==='vlsm'?vlsmPage(state.addressPlan):tab==='subnet'?subnetPage():tab==='terminal'?terminalPage():tab==='packet'?`<section class="card" id="simulation">${simulation()}</section>`:quizPage()}`;}
function subnetPage(){return `<div class="grid"><section class="card"><span class="eyebrow">FIND THE NETWORK BOUNDARY</span><h2 style="margin-top:15px">Which subnet contains this host?</h2><div class="row"><div class="field" style="flex:2"><label for="ip">IPv4 address</label><input id="ip" value="${esc(trainer.ip)}" inputmode="decimal"></div><div class="field" style="flex:1"><label for="prefix">Prefix length</label><select id="prefix">${Array.from({length:30},(_,i)=>i+1).map(n=>`<option value="${n}" ${n===trainer.prefix?'selected':''}>/${n}</option>`).join('')}</select></div></div><label for="subnet-answer">Your network address</label><input id="subnet-answer" placeholder="e.g. 192.168.8.64" value="${esc(trainer.answer)}"><div class="row section"><button class="primary" id="check-subnet">Check answer</button><button id="reveal-subnet">Show worked solution</button><button id="new-subnet">New problem</button></div><div id="subnet-feedback" aria-live="polite">${trainer.feedback}</div></section><section class="card" id="subnet-solution"><span class="eyebrow">WORKED SOLUTION</span>${trainer.result?`<h3 style="margin-top:18px">${trainer.result.network}/${trainer.prefix}</h3><table>${[['Subnet mask',trainer.result.mask],['Network',trainer.result.network],['First usable',trainer.result.first],['Last usable',trainer.result.last],['Broadcast',trainer.result.broadcast],['Usable hosts',trainer.result.hosts]].map(([k,v])=>`<tr><th>${k}</th><td>${v}</td></tr>`).join('')}</table><p class="small muted section">${32-trainer.prefix} host bits → 2<sup>${32-trainer.prefix}</sup> = ${trainer.result.size} addresses. Find the aligned block, then exclude network and broadcast.</p>`:'<h3 style="margin-top:18px">Try first, then compare.</h3><p class="muted">Count host bits, calculate block size, locate the boundary, and identify the usable range.</p><div class="callout small">Ordinary IPv4 subnets /1–/30. /31 and /32 have different rules.</div>'}</section></div>`;}
function terminalPage(){return `<section class="card"><div class="row between"><div><h2>Make a switch port belong.</h2><p class="muted small">Create VLAN 10, name it ENGINEERING, and put Fa0/1 in access mode in VLAN 10.</p></div><button id="reset-terminal">Reset sandbox</button></div><div class="terminal" id="terminal-output" role="log" aria-live="polite">${esc(lines.join('\n'))}</div><form id="terminal-form" class="row section"><label for="command">Command</label><input id="command" class="terminal-input" autocomplete="off" spellcheck="false" placeholder="enable" style="flex:1;min-width:180px"><button class="primary">Run</button></form><div id="terminal-result" class="section"></div><p class="footer-note">Limited IOS-style teaching sandbox. No commands go to Packet Tracer or your real network. Its configuration resets on reload.</p></section>`;}
function quizPage(){if(!quiz)return `<section class="card"><span class="eyebrow">ORIGINAL PRACTICE QUESTIONS</span><h2 style="margin-top:16px">Find the concepts to revisit.</h2><p class="muted">Choose a timed mixed check, then review explanations and revisit the relevant lessons.</p><div class="callout small">This original bank has ${questions.length} questions and may repeat across attempts. The balanced mode uses v2.0 domain proportions, but not every subtopic is covered. This is independent practice, not an official exam or a prediction of passing.</div><label for="quiz-focus">Practice focus</label><select id="quiz-focus" style="max-width:420px;margin-bottom:20px"><option value="all">All topics · prefer unseen questions</option><option value="weak">Missed topics first</option><option value="balanced">v2.0 domain-balanced · 60 questions</option>${modules.map(m=>`<option value="${m.id}">${esc(m.name)} · ${questions.filter(q=>q.module===m.id).length} questions</option>`).join('')}</select><p class="small muted">Balanced sessions use 60 questions with a 15/15/12/12/6 domain split. Focused sessions need enough questions for the selected length. Missed-topic practice uses your recent recorded answers; unseen questions are preferred within each priority group.</p><label for="quiz-size">Session length</label><select id="quiz-size" style="max-width:300px;margin-bottom:20px"><option value="10">10 questions · 15 minutes</option><option value="30">30 questions · 45 minutes</option><option value="60">60 questions · 90 minutes</option></select><div><button class="primary" id="start-quiz">Start knowledge check →</button></div></section>`;if(quiz.finished)return `<section class="card"><span class="eyebrow">KNOWLEDGE CHECK COMPLETE</span><h2 class="section">${quiz.questions.filter((q,i)=>quiz.answers[i]===q.question.answer).length} / ${quiz.questions.length} correct</h2><p class="muted">${quiz.saved?'Results saved to your history.':'Results have not been saved.'}</p><button id="new-quiz">Return to assessment start</button>${!quiz.saved?'<button id="retry-quiz">Retry saving</button>':''}${quiz.questions.map((l,i)=>`<section class="step section"><span class="badge ${quiz.answers[i]===l.question.answer?'green':''}">${quiz.answers[i]===l.question.answer?'Correct':'Revisit'}</span><h3 style="margin-top:14px">${esc(l.question.prompt)}</h3><p class="small muted">Your answer: ${esc(l.question.options[quiz.answers[i]]||'Unanswered')}</p><p>${esc(l.question.explanation)}</p><a href="#lesson/${l.id}">Review ${l.title} →</a></section>`).join('')}</section>`;const l=quiz.questions[quiz.index];return `<section class="card"><div class="row between"><span class="eyebrow">QUESTION ${quiz.index+1} OF ${quiz.questions.length}</span><span class="badge" id="quiz-time"></span></div><div class="progress"><div style="width:${pct(quiz.index,quiz.questions.length)}%"></div></div><h2 class="section">${esc(l.question.prompt)}</h2><div class="options">${l.question.options.map((o,i)=>`<button class="option ${quiz.answers[quiz.index]===i?'selected':''}" data-quiz-answer="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><div class="row between"><button id="quiz-prev" ${!quiz.index?'disabled':''}>← Previous</button><button id="quiz-next" class="primary">${quiz.index===quiz.questions.length-1?'Finish & review':'Next →'}</button></div></section>`;}
function reviewPage(){const available=due();if(!available.some(c=>c.id===reviewId)){reviewId=available[0]?.id;flipped=false;}const c=cards.find(x=>x.id===reviewId);return header('MAKE IT STICK','Spaced review','Recall the answer before revealing it. Your rating schedules the next review.')+(!c?`<section class="card empty"><h2>${state.completed.length?'You’re up to date.':'Build your first set of review cards.'}</h2><p class="muted">${state.completed.length?'No cards are due right now. Continue learning or practice a lab.':'Complete a lesson to add its key question to your review queue.'}</p><button class="primary" data-go="path">Explore lessons →</button></section>`:`<section class="card"><div class="row between"><span class="badge">${modules.find(m=>m.id===c.module).name}</span><span class="small muted">${available.length} due</span></div><div class="flashcard">${esc(flipped?c.answer:c.question)}</div><div class="row" style="justify-content:center">${flipped?[['again','Again · 10 min'],['hard','Hard · 1 day'],['good','Good'],['easy','Easy']].map(([r,t])=>`<button data-review="${r}" class="${r==='good'?'primary':''}">${t}</button>`).join(''):'<button class="primary" id="reveal-card">Reveal answer</button>'}</div></section>`);}
function notesPage(){return header('YOUR PERSONAL REFERENCE','My notes','Keep explanations, command output, and troubleshooting evidence together.')+`<section class="card">${noteBox('general','Study notebook')}</section><div class="notes-list section">${Object.entries(state.notes).filter(([k,v])=>k!=='general'&&v.trim()).map(([id,text])=>{const lab=id.startsWith('lab:'),item=lab?labs.find(l=>l.id===id.slice(4)):lessons.find(l=>l.id===id);return `<section class="card"><div class="row between"><h3>${esc(item?.title||id)}</h3>${item?`<button data-go="${lab?'lab':'lesson'}/${item.id}">Open →</button>`:''}</div><p style="white-space:pre-wrap">${esc(text)}</p></section>`;}).join('')}</div>`;}
function progressPage(){const total=state.attempts.reduce((s,a)=>s+a.total,0),score=state.attempts.reduce((s,a)=>s+a.score,0);return header('EVIDENCE OVER GUESSWORK','Your learning progress','Lesson completion, recall, and practice are different signals.')+`<div class="stats"><div class="card stat"><strong>${pct(state.completed.length,lessons.length)}%</strong><small>Starter lessons completed</small></div><div class="card stat"><strong>${total?pct(score,total)+'%':'—'}</strong><small>Recorded answer accuracy</small></div><div class="card stat"><strong>${labs.filter(labDone).length}</strong><small>Self-reported lab checklists</small></div></div><div class="grid"><section class="card"><h2>Progress by module</h2>${modules.map(m=>{const ls=lessons.filter(l=>l.module===m.id),n=ls.filter(l=>done(l.id)).length;return `<div class="section"><div class="row between"><strong class="small">${m.name}</strong><span class="small muted">${n}/${ls.length}</span></div><div class="progress"><div style="width:${pct(n,ls.length)}%"></div></div></div>`;}).join('')}</section><section class="card"><h2>Where to focus</h2>${state.attempts.filter(a=>a.score<a.total&&lessons.some(l=>l.id===a.lesson)).slice(-5).reverse().map(a=>`<p><a href="#lesson/${a.lesson}">${lessons.find(l=>l.id===a.lesson).title} →</a></p>`).join('')||'<p class="muted">Complete a knowledge check to identify topics for another look.</p>'}<div class="callout small"><strong>Exam readiness is not yet established.</strong><br>This release has concise starter coverage and a small question bank. Native lab validation, expanded assessments, and a full target-version audit remain necessary.</div><button data-tablink="assessment">Take a knowledge check →</button></section></div><section class="card section"><h2>Recent assessment history</h2>${state.attempts.length?`<div class="table-wrap"><table><thead><tr><th>Topic</th><th>Result</th><th>When</th></tr></thead><tbody>${state.attempts.slice(-20).reverse().map(a=>`<tr><td>${esc(lessons.find(l=>l.id===a.lesson)?.title||a.lesson)}</td><td>${a.score}/${a.total}</td><td>${esc(new Date(a.date).toLocaleString())}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Your saved attempts will appear here.</p>'}</section>`;}
function settingsPage(){return header('MAKE THIS SPACE YOURS','Settings & backups','Your learning history is stored on this computer, outside browser storage.')+`<div class="grid"><section class="card"><h2>Study preferences</h2><form id="settings-form"><div class="field"><label for="name">Your name</label><input id="name" maxlength="80" value="${esc(state.settings.name)}" required></div><div class="field"><label for="hours">Study hours per week</label><input id="hours" type="number" min="1" max="60" value="${state.settings.hours}" required></div><div class="field"><label for="exam-date">Target exam date (optional)</label><input id="exam-date" type="date" value="${esc(state.settings.examDate)}"></div><div class="field"><label for="exam-version">Exam target</label><select id="exam-version"><option value="undecided">Not decided yet</option><option value="v1.1" ${state.settings.examVersion==='v1.1'?'selected':''}>v1.1 · through February 2, 2027</option><option value="v2.0" ${state.settings.examVersion==='v2.0'?'selected':''}>v2.0 · from February 3, 2027</option></select></div><button class="primary">Save preferences</button></form><p class="small muted section">Preferences are saved for planning. Selecting v2.0 does not imply that this starter curriculum covers v2.0.</p></section><aside><section class="card"><h2>Your data, in your hands.</h2><p class="muted small">Progress, notes, attempts, review schedules, and lab checklists live in a local SQLite database. Snapshots are created at startup and before a change after a 10-minute interval. The latest 30 are retained.</p><div class="row"><button class="primary" id="export">Export backup</button><button id="backup">Create local snapshot</button></div><div class="section"><label for="restore">Restore a NetPath JSON backup</label><input type="file" id="restore" accept=".json,application/json"><p class="small muted">A recovery snapshot is created before a valid restore replaces progress. Copy exports to another drive for protection against computer failure.</p></div></section><section class="card section"><h3>Packet Tracer integration</h3><span class="badge">Companion mode</span><p class="small muted section">The installed build and extension interface still need testing. No live connection, simulator monitoring, or native .pkt/.pka files are included yet.</p></section></aside></div><section class="card section"><h2>Learning sources & scope</h2><p class="muted small">Original concise lessons and questions. Not affiliated with Cisco. Reference check: September 21, 2026.</p>${sources.map(s=>`<p><a href="${s.url}" target="_blank" rel="noreferrer">${s.title} ↗</a></p>`).join('')}</section>`;}
function missing(){return '<section class="card empty"><h1>Page not found.</h1><button data-go="overview">Return to overview</button></section>';}
function planPage(){const remaining=lessons.filter(l=>!done(l.id)),remainingLabs=labs.filter(l=>!labDone(l)),weekly=state.settings.hours*60,budget=Math.max(30,Math.floor(weekly*.8));const tasks=remaining.flatMap(l=>[{name:l.title,minutes:l.minutes,dest:'lesson/'+l.id,type:'Lesson'},...remainingLabs.filter(x=>x.lesson===l.id).map(x=>({name:x.title,minutes:x.minutes,dest:'lab/'+x.id,type:'Lab'}))]);for(const l of remainingLabs.filter(x=>!remaining.some(y=>y.id===x.lesson)))tasks.unshift({name:l.title,minutes:l.minutes,dest:'lab/'+l.id,type:'Lab'});const weeks=[];let current=[],used=0;for(const t of tasks){if(used+t.minutes>budget&&current.length){weeks.push(current);current=[];used=0;}current.push(t);used+=t.minutes;}if(current.length)weeks.push(current);return header('BUILD A SUSTAINABLE ROUTINE','Your study plan',`Based on ${state.settings.hours} hours per week. Adjust the pace as your understanding develops.`,'<button data-go="settings">Adjust preferences</button>')+`<div class="stats"><div class="card stat"><strong>${remaining.length}</strong><small>Lessons remaining</small></div><div class="card stat"><strong>${remainingLabs.length}</strong><small>Lab checklists remaining</small></div><div class="card stat"><strong>${weeks.length||0}</strong><small>Estimated content weeks</small></div></div><div class="grid"><section><h2>Your next study blocks</h2><p class="muted small">About 80% of your weekly time goes to new lessons and labs, with 20% reserved for recall and corrections. These estimates cover this library once; they do not predict your exam date.</p>${weeks.slice(0,8).map((week,i)=>`<section class="card section"><div class="row between"><h3>Week ${i+1}</h3><span class="badge">${week.reduce((n,t)=>n+t.minutes,0)} min + review</span></div>${week.map(t=>`<div class="step row between"><div class="grow"><span class="eyebrow">${t.type} · ${t.minutes} MIN</span><p style="margin:4px 0">${t.name}</p></div><button data-go="${t.dest}">Open →</button></div>`).join('')}</section>`).join('')||'<section class="card"><h3>Your first pass is complete.</h3><p>Use the objective tracker to choose weak areas and repeat labs independently.</p><button data-go="coverage">Review exam objectives →</button></section>'}${weeks.length>8?`<p class="muted section">${weeks.length-8} more content weeks follow. The plan recalculates as you complete work.</p>`:''}</section><aside><section class="card"><span class="eyebrow">A REPEATABLE SESSION</span><h3 class="section">Recall → learn → build → explain</h3><ol><li>Recall one earlier concept without looking.</li><li>Study a short lesson and predict the outcome.</li><li>Run the related lab and gather evidence.</li><li>Explain one mistake in your notebook.</li></ol><button class="primary" data-go="review">Start with recall →</button></section><section class="card section"><h3>Your exam target</h3><p>${state.settings.examDate?esc(state.settings.examDate):'No date selected yet.'}</p><p class="small muted">${state.settings.examVersion==='v2.0'?'Your target is v2.0. This content still needs a full audit against that blueprint.':'Current lessons reference v1.1. Check the official exam version before choosing your test date.'}</p><button data-go="coverage">Check coverage →</button></section></aside></div>`;}
function coveragePage(){const picker='<label for="coverage-version">Blueprint view</label><select id="coverage-version"><option value="v2.0" '+(coverageVersion==='v2.0'?'selected':'')+'>v2.0 · future exam planning</option><option value="v1.1" '+(coverageVersion==='v1.1'?'selected':'')+'>v1.1 · existing self-assessments</option></select>';if(coverageVersion==='v2.0')return header('PLAN YOUR COVERAGE','Exam-objective tracker','v2.0 planning map · reviewed September 25, 2026')+picker+v2CoverageMarkup(lessons,labs,state.completed);return picker+ header('A MAP OF WHAT TO LEARN','Exam-objective tracker','CCNA 200-301 v1.1 · top-level objectives and your self-assessment.')+`<div class="callout small">This maps ${objectives.length} top-level objectives to introductory lessons. It does not certify complete coverage of every subtopic. Ratings are your own assessment; “Practiced” does not mean NetPath verified a live lab.</div>${domains.map(d=>`<section class="card section"><div class="row between"><h2>${d.name}</h2><span class="badge">${d.weight}% exam weight</span></div><div class="table-wrap"><table><thead><tr><th>Objective</th><th>Lesson progress</th><th>Your confidence</th><th>Study</th></tr></thead><tbody>${objectives.filter(o=>o.domain===d.id).map(o=>`<tr><td><strong>${o.id}</strong> · ${o.title}</td><td><span class="badge ${done(o.lesson)?'green':''}">${done(o.lesson)?'Lesson studied':'Not studied'}</span></td><td><select data-confidence="${o.id}" aria-label="Confidence for ${o.id} ${o.title}">${[['0','Not assessed'],['1','I can explain it'],['2','I have practiced it']].map(([v,t])=>`<option value="${v}" ${String(state.confidence?.[o.id]||0)===v?'selected':''}>${t}</option>`).join('')}</select></td><td><button data-go="lesson/${o.lesson}">Open →</button></td></tr>`).join('')}</tbody></table></div></section>`).join('')}<p class="footer-note">Weights and objective IDs refer to v1.1. <a href="${sources[0].url}" target="_blank" rel="noreferrer">Read the official blueprint, including all subtopics ↗</a></p>`;}
function glossaryPage(){const matches=glossary.filter(([term,meaning])=>(term+' '+meaning).toLowerCase().includes(glossarySearch.toLowerCase()));return header('THE LANGUAGE OF NETWORKS','Networking glossary','Short definitions, with a lesson when you want the full explanation.')+`<div class="toolbar"><input id="glossary-search" class="search" aria-label="Search glossary" placeholder="Search a term, such as VLAN…" value="${esc(glossarySearch)}"><span class="small muted">${matches.length} terms</span></div><div class="lab-list">${matches.map(([term,meaning,lesson])=>`<section class="card"><h3>${term}</h3><p class="muted">${meaning}</p><button data-go="lesson/${lesson}">Explore the concept →</button></section>`).join('')||'<section class="card empty">No matching terms. Try a shorter search.</section>'}</div>`;}
function packetTracerPanel(){return `<section class="card" style="margin-bottom:28px"><div class="row between"><div><span class="eyebrow">PACKET TRACER ON THIS COMPUTER</span><h3 style="margin-top:10px">Practice side by side.</h3><p class="small muted" id="pt-status">Detected installation: 9.0.1.0858. Live simulator connection has not been established.</p></div><div class="row"><button class="primary" data-pt="launch">Open Packet Tracer</button><button data-pt="check">Check integration status</button></div></div><details><summary>Visual reference: where to find Simulation controls</summary><figure><img class="reference-image" src="/packet-tracer-help/mode_simulation_2.jpg" alt="Cisco help screenshot showing the Simulation tab at bottom right, Event List above, and playback and Edit Filters controls in the right panel." loading="lazy"><figcaption>Cisco’s installed Packet Tracer help illustration. The screenshot depicts an older interface and a QoS example; use it to locate controls, not as this lab’s topology. © Cisco.</figcaption></figure><ol><li>Select <strong>Simulation</strong> at the bottom right.</li><li>Use <strong>Edit Filters</strong> to show the protocols you are studying.</li><li>Advance one event with the rightmost playback control, <strong>Capture/Forward</strong>.</li><li>Select an event to inspect the PDU details.</li></ol></details></section>`;}
function render(){if(!state)return;document.body.classList.toggle('field-mode',route().page==='field');const {page,id}=route(),active=page==='lesson'?'path':page==='lab'?'labs':page;const body=page==='field'?fieldPage(state):page==='overview'?overview():page==='path'?pathPage():page==='lesson'?lessonPage(id):page==='labs'?labsPage():page==='lab'?labPage(id):page==='practice'?practicePage():page==='practitioner'?practitionerPage(state):page==='workbench'?workbenchPage(state):page==='review'?reviewPage():page==='notes'?notesPage():page==='progress'?progressPage():page==='settings'?settingsPage():page==='plan'?planPage():page==='coverage'?coveragePage():page==='glossary'?glossaryPage():missing();app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="/favicon.svg" alt="">Net<span>Path</span></div><div class="eyebrow" style="margin-top:15px">Your networking classroom</div><nav aria-label="Main navigation">${navigation(active)}</nav><div class="sidebar-foot"><span class="eyebrow">FOUNDATIONS → CCNA</span><div class="progress"><div style="width:${pct(state.completed.length,lessons.length)}%"></div></div>${state.completed.length} of ${lessons.length} lessons completed<br><span class="pill">Local database · personal workspace</span></div></aside><main class="main"><header class="topbar"><span class="crumb">Workspace / ${esc(navs.find(([k])=>k===active)?.[1]||'Learning')}</span><div class="topbar-actions"><button class="ghost" id="theme" aria-label="Switch to ${document.body.classList.contains('light')?'dark':'light'} mode">${document.body.classList.contains('light')?'☾ Dark':'☀ Light'}</button><div class="avatar">${esc(state.settings.name.slice(0,1).toUpperCase())}</div></div></header><div class="content">${["labs","lab","settings"].includes(page)?packetTracerPanel():""}${body}<p class="footer-note">NetPath · Learn with intention. Practice with evidence.</p></div></main></div>`;bind();tick();}
function download(name,text,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function persistQuiz(){const draft={questionIds:quiz.questions.map(l=>l.qid),answers:[...quiz.answers],index:quiz.index,deadline:quiz.deadline};return save(s=>s.activeQuiz=draft);}
async function flushNote(){clearTimeout(noteTimer);const el=$('[data-note]');if(el&&el.value!==(state.notes[el.dataset.note]||'')){const key=el.dataset.note,value=el.value;return save(s=>s.notes[key]=value);}return true;}
async function finishQuiz(){if(busy||!quiz||quiz.saved)return;busy=true;quiz.finished=true;quiz.saved=await save(s=>{quiz.questions.forEach((l,i)=>s.attempts.push({lesson:l.id,qid:l.qid,score:quiz.answers[i]===l.question.answer?1:0,total:1,date:new Date().toISOString(),kind:'mixed'}));s.activeQuiz=null;});busy=false;if(await flushNote())render();}
function tick(){if(quiz&&!quiz.finished){const seconds=Math.max(0,Math.ceil((quiz.deadline-Date.now())/1000));if($('#quiz-time'))$('#quiz-time').textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')} remaining`;if(!seconds)finishQuiz();}}
function bindSim(){$$('[data-sim]').forEach(b=>b.onclick=()=>{step=Math.max(0,Math.min(5,step+Number(b.dataset.sim)));$('#simulation').innerHTML=simulation();bindSim();});}
function bind(){
bindField({save,render,toast});
bindPractitioner({api,render,toast});
bindWorkbench({save,render,toast});
$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('#theme').onclick=async()=>{if(!await flushNote())return;document.body.classList.toggle('light');localStorage.setItem('netpath-theme',document.body.classList.contains('light')?'light':'dark');render();};
$$('[data-module]').forEach(b=>b.onclick=()=>{filter=b.dataset.module;go('path');});$('#filter')?.addEventListener('change',e=>{filter=e.target.value;render();});$('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);});
const note=$('[data-note]');if(note)note.oninput=()=>{clearTimeout(noteTimer);$('#note-status').textContent='Saving…';noteTimer=setTimeout(async()=>{const ok=await flushNote();if($('#note-status'))$('#note-status').textContent=ok?'Saved to your local database.':'Not saved. Keep this text and retry when connected.';},450);};
$$('[data-answer]').forEach(b=>b.onclick=async()=>{const l=lessons.find(x=>x.id===b.dataset.lesson),correct=Number(b.dataset.answer)===l.question.answer;$$('[data-answer]').forEach(x=>x.disabled=true);b.classList.add('selected');$('#lesson-feedback').innerHTML=`<div class="feedback"><strong>${correct?'Correct.':'Let’s unpack that.'}</strong><p style="margin:8px 0 0">${esc(l.question.explanation)}</p></div>`;await save(s=>s.attempts.push({lesson:l.id,score:correct?1:0,total:1,date:new Date().toISOString(),kind:'lesson'}));});
$('#complete')?.addEventListener('click',async e=>{const id=e.currentTarget.dataset.id;if(done(id)){toast('This lesson is already complete.');return;}e.currentTarget.disabled=true;await flushNote();if(await save(s=>{s.completed.push(id);s.lastLesson=id;})){toast('Lesson complete. Your review card is ready.');render();}else e.target.disabled=false;});
$$('[data-lab]').forEach(el=>el.onchange=async()=>{const checked=el.checked,id=el.dataset.lab,i=Number(el.dataset.step);el.disabled=true;const ok=await save(s=>{s.labs[id]=checked?[...new Set([...(s.labs[id]||[]),i])]:(s.labs[id]||[]).filter(x=>x!==i);});el.disabled=false;if(!ok)el.checked=!checked;else toast('Lab checkpoint saved.');});bindSim();
$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});$$('[data-tablink]').forEach(b=>b.onclick=()=>{tab=b.dataset.tablink;go('practice');});
$('#copy')?.addEventListener('click',async e=>{try{await navigator.clipboard.writeText(labs.find(l=>l.id===e.currentTarget.dataset.id).commands);toast('Commands copied.');}catch{toast('Select the command text and copy manually.');}});
$('#download-lab')?.addEventListener('click',e=>{const l=labs.find(l=>l.id===e.currentTarget.dataset.id);download(`NetPath-${l.id}-guide.txt`,`${l.title}\n${l.subtitle}\n\nCompanion guide; not a native Packet Tracer file. Not yet tested in your installed build.\n\nWIRING\n${topologyText(l.id)}\n\nADDRESSING\n${l.addresses.map(a=>a.join(' | ')).join('\n')}\n\n${l.steps.map((s,i)=>`${i+1}. ${s.title}\n${s.action}\nExpected: ${s.expected}\nHint: ${s.hint}`).join('\n\n')}\n\nCommands:\n${l.commands}\n\nChallenge: ${l.challenge}`);});
const calc=()=>{trainer.ip=$('#ip').value.trim();trainer.prefix=Number($('#prefix').value);trainer.answer=$('#subnet-answer').value.trim();return subnet(trainer.ip,trainer.prefix);};
$('#check-subnet')?.addEventListener('click',async()=>{try{const r=calc();if(!trainer.answer){toast('Enter your network address first.');return;}const correct=trainer.answer===r.network;trainer.feedback=`<div class="feedback">${correct?'Correct. That is the network boundary.':'Not quite. Count host bits and locate the aligned block containing the address.'}</div>`;await save(s=>s.attempts.push({lesson:'Subnetting trainer',score:correct?1:0,total:1,date:new Date().toISOString(),kind:'subnet'}));render();}catch(e){toast(e.message);}});
$('#reveal-subnet')?.addEventListener('click',()=>{try{trainer.result=calc();render();}catch(e){toast(e.message);}});$('#new-subnet')?.addEventListener('click',()=>{trainer={ip:`172.16.${Math.floor(Math.random()*256)}.${1+Math.floor(Math.random()*253)}`,prefix:shuffled([20,22,24,25,26,27,28,29,30])[0],result:null,answer:'',feedback:''};render();});
const invalidate=()=>{trainer.result=null;trainer.feedback='';$('#subnet-feedback').innerHTML='';$('#subnet-solution').innerHTML='<span class="eyebrow">WORKED SOLUTION</span><p class="section muted">Problem changed. Check your answer or reveal the updated solution.</p>';};$('#ip')?.addEventListener('input',invalidate);$('#prefix')?.addEventListener('change',invalidate);
$('#terminal-form')?.addEventListener('submit',e=>{e.preventDefault();const input=$('#command'),raw=input.value,r=terminalCommand(terminal,raw);lines.push(r.prompt+raw);if(r.out)lines.push(r.out);$('#terminal-output').textContent=lines.slice(-70).join('\n');input.value='';input.focus();const ok=terminal.vlans[10]==='ENGINEERING'&&terminal.interfaces['fastethernet0/1'].vlan===10&&terminal.interfaces['fastethernet0/1'].mode==='access';$('#terminal-result').innerHTML=ok?'<div class="feedback">Task verified in this sandbox: VLAN 10 is ENGINEERING and Fa0/1 is an access member. Now reproduce it in Packet Tracer.</div>':'';});$('#reset-terminal')?.addEventListener('click',()=>{terminal=createTerminal();lines=['Sandbox reset. Type help for supported commands.'];render();});
$('#start-quiz')?.addEventListener('click',async()=>{try{const selected=selectPractice(questions,Number($('#quiz-size').value),$('#quiz-focus').value,state.attempts);quiz={questions:selected,answers:[],index:0,deadline:Date.now()+selected.length*90000,finished:false,saved:false};if(await persistQuiz())render();else quiz=null;}catch(error){toast(error.message);}});$$('[data-quiz-answer]').forEach(b=>b.onclick=()=>{quiz.answers[quiz.index]=Number(b.dataset.quizAnswer);persistQuiz();render();});$('#quiz-prev')?.addEventListener('click',()=>{quiz.index--;persistQuiz();render();});$('#quiz-next')?.addEventListener('click',()=>{if(quiz.index<quiz.questions.length-1){quiz.index++;persistQuiz();render();}else finishQuiz();});$('#new-quiz')?.addEventListener('click',()=>{quiz=null;render();});$('#retry-quiz')?.addEventListener('click',finishQuiz);
$('#reveal-card')?.addEventListener('click',()=>{flipped=true;render();});$$('[data-review]').forEach(b=>b.onclick=async()=>{const id=reviewId;$$('[data-review]').forEach(x=>x.disabled=true);if(await save(s=>s.cards[id]=nextReview(s.cards[id],b.dataset.review))){reviewId=null;flipped=false;}render();});
$('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const settings={name:$('#name').value.trim()||'Learner',hours:Number($('#hours').value),examDate:$('#exam-date').value,examVersion:$('#exam-version').value};if(settings.examDate>='2027-02-03'&&settings.examVersion==='v1.1'){toast('That date is after the announced v1.1 exam window.');return;}if(settings.examDate&&settings.examDate<'2027-02-03'&&settings.examVersion==='v2.0'){toast('Cisco announces v2.0 from February 3, 2027.');return;}if(await save(s=>s.settings={...s.settings,...settings})){toast('Preferences saved.');render();}});
$('#export')?.addEventListener('click',async()=>{await queue;download('netpath-backup.json',JSON.stringify(state,null,2),'application/json');});$('#backup')?.addEventListener('click',async()=>{try{await queue;await api('/api/backup',{});toast('Recovery snapshot created.');}catch(e){toast(e.message);}});
$('#restore')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Backup is too large.');const incoming=JSON.parse(await file.text());if(!confirm('Replace progress with this backup? A recovery snapshot of current saved data will be created first.')){e.target.value='';return;}await queue;state=(await api('/api/restore',incoming)).state;quiz=null;toast('Backup restored.');render();}catch(error){toast('Restore failed: '+error.message);e.target.value='';}});
}
window.addEventListener('hashchange',async()=>{if(!await flushNote()){toast('Navigation paused to preserve your unsaved note.');return;}render();window.scrollTo(0,0);});window.addEventListener('beforeunload',e=>{const el=$('[data-note]');if(el&&el.value!==(state?.notes[el.dataset.note]||'')){e.preventDefault();e.returnValue='';}});
try{document.body.classList.toggle('light',localStorage.getItem('netpath-theme')==='light');const r=await api('/api/state');state=r.state;token=r.token;if(state.activeQuiz){quiz={...state.activeQuiz,questions:state.activeQuiz.questionIds.map(id=>questions.find(q=>q.qid===id)||questions.find(q=>q.id===id)),finished:false,saved:false};tab='assessment';}render();setInterval(tick,1000);}catch(e){app.innerHTML=`<div class="card" style="max-width:650px;margin:10vh auto"><h1>We couldn’t open your workspace.</h1><p>${esc(e.message)}</p><p>Make sure NetPath is running and refresh. Your saved database has not been changed.</p></div>`;}
if(state&&document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'read_learning_progress',description:'Read locally saved lesson and lab progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({completedLessons:state.completed,labChecklists:state.labs,reviewCardsDue:due().length})});await document.modelContext.registerTool({name:'open_networking_lesson',description:'Open a lesson without marking it complete.',inputSchema:{type:'object',properties:{lessonId:{type:'string',enum:lessons.map(l=>l.id)}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async({lessonId})=>{if(!lessons.some(l=>l.id===lessonId))throw Error('Unknown lesson');if(!await flushNote())throw Error('Unsaved notes');location.hash='lesson/'+lessonId;render();return {openedLesson:lessonId};}});}catch(e){console.warn('Optional learning tools unavailable',e);}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-pt]');if(!b)return;b.disabled=true;try{if(b.dataset.pt==='launch'){const r=await api('/api/packet-tracer/launch',{});toast(r.message);}else{const r=await api('/api/packet-tracer');$('#pt-status').textContent=r.installed?`Packet Tracer ${r.version} installed. Extension framework: ${r.framework?'present':'not found'}. Local IPC port: ${r.listenerReachable?'reachable (handshake not verified)':'not reachable at the default port'}. Live grading is not connected.`:'Packet Tracer was not found at the configured path.';}}catch(error){toast(error.message);}finally{b.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='glossary-search'){const pos=e.target.selectionStart;glossarySearch=e.target.value;render();$('#glossary-search').focus();$('#glossary-search').setSelectionRange(pos,pos);}});
document.addEventListener('change',async e=>{const key=e.target.dataset.confidence;if(!key)return;const value=Number(e.target.value);e.target.disabled=true;if(await save(s=>{s.confidence??={};s.confidence[key]=value;}))toast('Self-assessment saved.');e.target.disabled=false;});

document.addEventListener('change',e=>{if(e.target.id!=='topology-device')return;const id=e.target.dataset.topology,value=e.target.value;$('#lab-topology').innerHTML=topologyMarkup(id,value);$('#topology-device').focus();});

function rememberEvidenceDraft(form){const id=form.dataset.evidenceLab; evidenceDrafts[id]=Object.fromEntries(new FormData(form));try{localStorage.setItem('netpath-evidence-drafts',JSON.stringify(evidenceDrafts));const status=$('#evidence-draft-status');if(status)status.textContent='Draft saved in this browser. Choose Record test to include it in database backups.';}catch{toast('Browser draft storage is unavailable. Record this test before leaving the page.');}}
document.addEventListener('input',e=>{const form=e.target.closest('#evidence-form');if(form)rememberEvidenceDraft(form);});
document.addEventListener('change',e=>{const form=e.target.closest('#evidence-form');if(form)rememberEvidenceDraft(form);});
document.addEventListener('submit',async e=>{if(e.target.id!=='evidence-form')return;e.preventDefault();const form=e.target,id=form.dataset.evidenceLab,button=form.querySelector('[type=submit]'),values=Object.fromEntries(new FormData(form));const record={...values,id:crypto.randomUUID(),date:new Date().toISOString()};try{validateEvidence({[id]:[...(state.evidence?.[id]||[]),record]},labs.map(l=>l.id));}catch(error){toast(error.message);return;}button.disabled=true;if(!await flushNote()){button.disabled=false;return;}const ok=await save(s=>{s.evidence??={};s.evidence[id]??=[];s.evidence[id].push(record);});if(ok){delete evidenceDrafts[id];try{localStorage.setItem('netpath-evidence-drafts',JSON.stringify(evidenceDrafts));}catch{}const panel=$('#evidence-panel');if(panel&&route().id===id)panel.outerHTML=evidencePanel(id,state.evidence[id]);toast('Test evidence saved to your database.');}else button.disabled=false;});
document.addEventListener('click',e=>{const b=e.target.closest('#export-evidence');if(!b)return;const id=b.dataset.id,l=labs.find(l=>l.id===id);download('NetPath-'+id+'-test-log.txt',evidenceText(l.title,state.evidence?.[id]||[]));});

document.addEventListener('submit',async e=>{if(e.target.id!=='vlsm-form')return;e.preventDefault();const plan={network:$('#vlsm-network').value.trim(),prefix:Number($('#vlsm-prefix').value),requirements:$('#vlsm-requirements').value.trim()},button=e.target.querySelector('[type=submit]');let result;try{result=allocateVlsm(plan);}catch(error){$('#vlsm-message').textContent=error.message;$('#vlsm-result').innerHTML='';return;}button.disabled=true;const ok=await save(s=>s.addressPlan=plan);button.disabled=false;if(route().page==='practice'&&tab==='vlsm'){$('#vlsm-message').textContent=ok?'Plan calculated and saved to your database.':'Plan was not saved. Keep your inputs and retry.';if(ok)$('#vlsm-result').innerHTML=vlsmResult(result);}});
document.addEventListener('input',e=>{if(!e.target.closest('#vlsm-form'))return;$('#vlsm-result').innerHTML='';$('#vlsm-message').textContent='Edited inputs are not saved yet. Calculate to update the plan.';});
document.addEventListener('change',e=>{if(!e.target.closest('#vlsm-form'))return;$('#vlsm-result').innerHTML='';$('#vlsm-message').textContent='Edited inputs are not saved yet. Calculate to update the plan.';});
document.addEventListener('click',e=>{if(!e.target.closest('#export-vlsm')||!state.addressPlan)return;download('NetPath-address-plan.txt',vlsmText(allocateVlsm(state.addressPlan)));});

document.addEventListener('change',e=>{if(e.target.id==='coverage-version'){coverageVersion=e.target.value;render();$('#coverage-version').focus();}});

document.addEventListener('change',async e=>{if(e.target.id!=='simple-mode')return;const value=e.target.checked;e.target.disabled=true;if(!await flushNote()){e.target.disabled=false;e.target.checked=!value;return;}if(await save(s=>s.settings.simpleLessons=value))render();else{e.target.disabled=false;e.target.checked=!value;}});

function navigation(active){const groups=[['Learn',['path','glossary']],['Field lab',['field','labs','workbench']],['Exams',['practice','practitioner','coverage']],['My workspace',['overview','review','notes','progress','plan','settings']]];return groups.map(([title,keys])=>`<details class="nav-group" ${keys.includes(active)?'open':''}><summary>${title}</summary>${keys.map(key=>{const [,label]=navs.find(n=>n[0]===key);return `<button class="nav ${active===key?'active':''}" data-go="${key}" ${active===key?'aria-current="page"':''}>${label}</button>`;}).join('')}</details>`).join('');}
